const crypto = require('crypto');

if (!$json.token_valid_structure) {
  return [{
    json: {
      ...$json,
      token_verified: false,
      token_error: $json.token_error ?? 'INVALID_TOKEN_STRUCTURE'
    }
  }];
}

const secret = $env.PROPOSAL_ACCEPT_HMAC_SECRET;
if (!secret) {
  throw new Error('3.0.1.4: PROPOSAL_ACCEPT_HMAC_SECRET is not configured');
}

const leadId = String($json.accept_token_lead_id);
const expiresAt = Number($json.accept_token_expires_at);
const suppliedSignature = String($json.accept_token_signature);

const payload = `${leadId}.${expiresAt}`;

const expectedSignature = crypto
  .createHmac('sha256', secret)
  .update(payload, 'utf8')
  .digest('hex');

const signaturesMatch =
  suppliedSignature.length === expectedSignature.length &&
  crypto.timingSafeEqual(
    Buffer.from(suppliedSignature, 'utf8'),
    Buffer.from(expectedSignature, 'utf8')
  );

const now = Math.floor(Date.now() / 1000);
const notExpired = Number.isInteger(expiresAt) && expiresAt > now;

return [{
  json: {
    ...$json,
    token_signature_valid: signaturesMatch,
    token_not_expired: notExpired,
    token_verified: signaturesMatch && notExpired,
    token_verified_at: new Date().toISOString(),
    token_error: signaturesMatch
      ? (notExpired ? null : 'ACCEPT_TOKEN_EXPIRED')
      : 'ACCEPT_TOKEN_SIGNATURE_INVALID'
  }
}];
